#!/usr/bin/env python3
"""Read-only transitive Lean import closure over git HEAD blobs (pinned SHA)."""
import subprocess, sys, hashlib, os
from collections import deque

GD   = "/home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/vcs/workspace.git"
WS   = "/home/axel/LeanAlgebraicGeometry-Horizon"
PROJ = "MainProjects/Algebraic-Jacobian-Challenge-Rebuild"
SUB  = PROJ + "/AlgebraicJacobian"
SHA  = open("/tmp/pinned_sha.txt").read().strip()

def git(*args, binary=False):
    r = subprocess.run(["git", "--git-dir=" + GD] + list(args),
                       capture_output=True, cwd=WS)
    if r.returncode != 0:
        raise RuntimeError(" ".join(args) + " -> " + r.stderr.decode()[:300])
    return r.stdout if binary else r.stdout.decode("utf-8", "replace")

# ---- 1. list .lean files at pinned SHA -------------------------------------
all_paths = git("ls-tree", "-r", "--name-only", "--full-tree", SHA).splitlines()
lean = [p for p in all_paths
        if p.endswith(".lean") and (p.startswith(SUB + "/") or p == PROJ + "/AlgebraicJacobian.lean")]

# ---- 3. module <-> path ----------------------------------------------------
def path_to_mod(p):
    rel = p[len(PROJ) + 1:]            # AlgebraicJacobian/Picard/Foo.lean
    return rel[:-5].replace("/", ".")  # AlgebraicJacobian.Picard.Foo

def mod_to_path(m):
    return PROJ + "/" + m.replace(".", "/") + ".lean"

mods = {path_to_mod(p): p for p in lean}

# ---- 2. extract imports ---------------------------------------------------
edges, ext_imports, missing = {}, {}, {}
blobs = {}
for m, p in sorted(mods.items()):
    txt = git("show", SHA + ":" + p)
    blobs[m] = txt
    local, ext = [], []
    for line in txt.splitlines():
        if not line.startswith("import"):
            continue                     # column-0 `import` only
        parts = line.split()
        if len(parts) < 2:
            continue
        tgt = parts[1] if parts[1] != "public" else (parts[2] if len(parts) > 2 else None)
        if not tgt:
            continue
        if tgt.startswith("AlgebraicJacobian"):
            if tgt in mods:
                local.append(tgt)
            else:
                missing.setdefault(m, []).append(tgt)
        else:
            ext.append(tgt)
    edges[m] = local
    if ext:
        ext_imports[m] = ext

# ---- 4. transitive closure + shortest chain -------------------------------
def closure(root):
    """BFS -> (set of reachable local modules excluding root, parent map)."""
    seen, par, q = {root}, {}, deque([root])
    while q:
        cur = q.popleft()
        for nxt in edges.get(cur, []):
            if nxt not in seen:
                seen.add(nxt); par[nxt] = cur; q.append(nxt)
    seen.discard(root)
    return seen, par

def chain(root, target, par):
    out, cur = [target], target
    while cur in par:
        cur = par[cur]; out.append(cur)
    return list(reversed(out))

def fmt(root, target):
    cl, par = closure(root)
    if target not in cl:
        return "NO", None
    return "YES", " -> ".join(chain(root, target, par))

# ---- 5. disk blob vs HEAD blob -------------------------------------------
def blob_matches(m):
    disk = os.path.join(WS, mods[m])
    if not os.path.exists(disk):
        return "MISSING_ON_DISK"
    head_oid = git("rev-parse", SHA + ":" + mods[m]).strip()
    disk_oid = subprocess.run(["git", "hash-object", os.path.join(WS, mods[m])],
                              capture_output=True, cwd=WS).stdout.decode().strip()
    return "SAME" if head_oid == disk_oid else "DIFFERS"

TGT  = "AlgebraicJacobian.Picard.DivSchemeMonoBridgeRel"
FORK = "AlgebraicJacobian.Picard.Pic0ChartAbelForkReduce"
Q1 = ["AlgebraicJacobian.Picard.Pic0ChartPair",
      "AlgebraicJacobian.Picard.Pic0ChartUnivReduce",
      "AlgebraicJacobian.Picard.Pic0ChartOpenImmersionCriterion",
      "AlgebraicJacobian.Picard.Pic0ChartAbelNonInjective",
      "AlgebraicJacobian.Picard.Pic0ChartRestrictedFibre"]
Q5 = ["AlgebraicJacobian.Picard.CechKernelLemma",
      "AlgebraicJacobian.Picard.RelPic",
      "AlgebraicJacobian.Picard.DivSchemeAbel",
      "AlgebraicJacobian.Picard.DivisorFamilyZarVehicle",
      "AlgebraicJacobian.Picard.EtaleSeparatedness",
      "AlgebraicJacobian.Picard.DivisorFamilyWindow"]  # defines divFamEps

print("PINNED SHA:", SHA)
print("lean files at HEAD:", len(mods), " target in tree:", TGT in mods)
print("\n=== Q1 ===")
for m in Q1:
    if m not in mods: print(f"{m}: MODULE_ABSENT_AT_HEAD"); continue
    a, c = fmt(m, TGT); print(f"{m}: {a}" + (f"\n    {c}" if c else ""))
print("\n=== Q2 ===")
a, c = fmt(FORK, TGT); print(f"{FORK}: {a}" + (f"\n    {c}" if c else ""))

print("\n=== Q3 direct importers ===")
direct = sorted(m for m, v in edges.items() if TGT in v)
for m in direct: print(" ", m)
print("count:", len(direct))
print("=== Q3 all modules whose closure contains target ===")
contain = sorted(m for m in mods if TGT in closure(m)[0])
for m in contain: print(" ", m)
print("count:", len(contain))

print("\n=== Q4 rooted from AlgebraicJacobian.lean ===")
a, c = fmt("AlgebraicJacobian", TGT); print(f"root: {a}" + (f"\n    {c}" if c else ""))

print("\n=== Q5 ===")
for m in Q5:
    if m not in mods: print(f"{m}: MODULE_ABSENT_AT_HEAD"); continue
    a, c = fmt(FORK, m); print(f"{m}: {a}" + (f"\n    {c}" if c else ""))

fcl, _ = closure(FORK)
print("\n=== Q6 ===")
print("closure size (excl self):", len(fcl), " incl self:", len(fcl) + 1)

print("\n=== blob disk-vs-HEAD for reported modules ===")
for m in sorted(set(Q1 + Q5 + [FORK, TGT, "AlgebraicJacobian"] + direct + contain)):
    if m in mods:
        st = blob_matches(m)
        if st != "SAME": print(f"  {m}: {st}")
print("  (only non-SAME listed)")

if missing:
    print("\n=== unresolved AlgebraicJacobian.* imports ===")
    for m, v in sorted(missing.items()):
        print(f"  {m}: {v}")

print("\n=== divFamEps grep at HEAD ===")
for m, t in blobs.items():
    for ln in t.splitlines():
        if "divFamEps" in ln and (" divFamEps " in ln or ln.rstrip().endswith("divFamEps")) and ("def " in ln or "abbrev" in ln):
            print(f"  {m}: {ln.strip()[:110]}")

#!/usr/bin/env python3
"""Re-verify disk-vs-HEAD for reported modules, and recompute closure from DISK too."""
import subprocess, os
from collections import deque

GD="/home/axel/LeanAlgebraicGeometry-Horizon/.archon-horizon/vcs/workspace.git"
WS="/home/axel/LeanAlgebraicGeometry-Horizon"
PROJ="MainProjects/Algebraic-Jacobian-Challenge-Rebuild"
SUB=PROJ+"/AlgebraicJacobian"
SHA="345b2f4d8d5539f4ef92aa1c06ac2bdb93952604"

def sh(args, cwd=WS):
    r=subprocess.run(args, capture_output=True, cwd=cwd)
    return r.returncode, r.stdout.decode("utf-8","replace"), r.stderr.decode("utf-8","replace")

_,out,_ = sh(["git","--git-dir="+GD,"ls-tree","-r","--name-only","--full-tree",SHA])
lean=[p for p in out.splitlines() if p.endswith(".lean") and (p.startswith(SUB+"/") or p==PROJ+"/AlgebraicJacobian.lean")]
def p2m(p): return p[len(PROJ)+1:][:-5].replace("/",".")
mods={p2m(p):p for p in lean}

TGT="AlgebraicJacobian.Picard.DivSchemeMonoBridgeRel"
FORK="AlgebraicJacobian.Picard.Pic0ChartAbelForkReduce"
REPORT=[FORK,TGT,"AlgebraicJacobian",
 "AlgebraicJacobian.Picard.Pic0ChartPair","AlgebraicJacobian.Picard.Pic0ChartUnivReduce",
 "AlgebraicJacobian.Picard.Pic0ChartOpenImmersionCriterion",
 "AlgebraicJacobian.Picard.Pic0ChartAbelNonInjective",
 "AlgebraicJacobian.Picard.Pic0ChartRestrictedFibre",
 "AlgebraicJacobian.Picard.CechKernelLemma","AlgebraicJacobian.Picard.RelPic",
 "AlgebraicJacobian.Picard.DivSchemeAbel","AlgebraicJacobian.Picard.DivisorFamilyZarVehicle",
 "AlgebraicJacobian.Picard.EtaleSeparatedness","AlgebraicJacobian.Picard.DivisorFamilyWindow",
 "AlgebraicJacobian.Picard.DivRepClassifyZarSep"]

print("=== disk vs HEAD (all 771 modules; listing non-SAME) ===")
diff=[]
for m,p in sorted(mods.items()):
    rc,h,_=sh(["git","--git-dir="+GD,"rev-parse",SHA+":"+p]); h=h.strip()
    ap=os.path.join(WS,p)
    if not os.path.exists(ap): diff.append((m,"MISSING_ON_DISK")); continue
    rc2,d,e2=sh(["git","--git-dir="+GD,"hash-object","--",ap]); d=d.strip()
    if rc2!=0 or not d: diff.append((m,"HASH_FAILED:"+e2.strip()[:80])); continue
    if h!=d: diff.append((m,"DIFFERS"))
for m,s in diff: print(f"  {s}  {m}   ({os.path.join(WS,mods[m])})")
print("  total non-SAME:",len(diff))
print("  of reported modules:",[m for m,s in diff if m in REPORT])

def imports(txt):
    o=[]
    for line in txt.splitlines():
        if line.startswith("import"):
            ps=line.split()
            if len(ps)>=2:
                t=ps[1] if ps[1]!="public" else (ps[2] if len(ps)>2 else None)
                if t and t.startswith("AlgebraicJacobian"): o.append(t)
    return o

def build(source):
    e={}
    for m,p in mods.items():
        if source=="head":
            _,t,_=sh(["git","--git-dir="+GD,"show",SHA+":"+p])
        else:
            ap=os.path.join(WS,p)
            t=open(ap,encoding="utf-8",errors="replace").read() if os.path.exists(ap) else ""
        e[m]=[x for x in imports(t) if x in mods]
    return e

def clos(e,root):
    seen,par,q={root},{},deque([root])
    while q:
        c=q.popleft()
        for n in e.get(c,[]):
            if n not in seen: seen.add(n);par[n]=c;q.append(n)
    seen.discard(root); return seen,par

eh=build("head"); ed=build("disk")
for lbl,e in (("HEAD",eh),("DISK",ed)):
    cl,_=clos(e,FORK)
    print(f"=== {lbl}: ForkReduce closure size={len(cl)} (incl self {len(cl)+1}); TGT in closure: {TGT in cl}")
    print(f"    {lbl} ForkReduce direct imports: {e[FORK]}")
    direct=sorted(m for m,v in e.items() if TGT in v)
    contain=sorted(m for m in mods if TGT in clos(e,m)[0])
    print(f"    {lbl} direct importers of TGT ({len(direct)}): {direct}")
    print(f"    {lbl} closure-contains TGT ({len(contain)}): {contain}")
